(* Generated snapshot of the catwalk [/v2/providers] catalog, pinned to
   .references/catwalk/internal/providers/configs (catwalk 3260272,
   2026-09-14). Provider rows follow the upstream registry order and
   model rows the upstream file order. pioneer is served by no registry
   entry upstream and azure, bedrock, bedrock-europe and vertexai are
   the cloud IAM stacks the plan cuts. Regenerate, never hand-edit.

   A row is the catwalk model members in wire order: id, name,
   cost_per_1m_in, cost_per_1m_out, cost_per_1m_in_cached,
   cost_per_1m_out_cached, context_window, default_max_tokens,
   can_reason, supports_attachments. [m] maps them onto [Model.t],
   crossing the cache costs: the fifth field prices cache creation and
   is [Model.cost_cache_write], the sixth prices cache reads and is
   [Model.cost_cache_read]. *)

let m provider
    ( id,
      name,
      cost_in,
      cost_out,
      cache_write,
      cache_read,
      context_window,
      default_max_tokens,
      can_reason,
      supports_attachments ) =
  {
    Model.id;
    name;
    provider;
    context_window;
    default_max_tokens;
    can_reason;
    supports_attachments;
    cost_in;
    cost_out;
    cost_cache_read = cache_read;
    cost_cache_write = cache_write;
  }

let providers : Provider_info.t list =
  let p id name base_url rows =
    { Provider_info.id; name; base_url; models = List.rev (List.rev_map (m id) rows) }
  in
